package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The values in force of a sheet's dated settings: on a date, the value recorded with the latest
 * from-date on or before it, and before every from-date the sheet's starting value (floor 1.00, late
 * percent 0.00, terms 14 days; no clerk limit, no cap, no proof threshold, no grade's own proof threshold, no note threshold, no review threshold, no grade's own terms and no grade's grace days). A claim's floor, late
 * percent, terms, proof threshold, note threshold and review threshold are those in force on its date; the clerk limit and the cap those on the sheet's
 * today. */
@Service
public class DatedSettings {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";
    public static final String REVIEW_THRESHOLD = "review-threshold";
    public static final String GRACE = "grace";
    public static final String ROUNDING = "rounding";
    public static final String HALF_UP = "half-up";
    public static final String HALF_EVEN = "half-even";

    public static final BigDecimal FLOOR_START = new BigDecimal("1.00");
    public static final BigDecimal LATE_PCT_START = new BigDecimal("0.00");
    public static final int TERMS_START = 14;

    private final SheetSettingRepository settings;
    private final SheetRepository sheets;

    public DatedSettings(SheetSettingRepository settings, SheetRepository sheets) {
        this.settings = settings;
        this.sheets = sheets;
    }

    /** The key a grade's own terms are kept under. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** The key a grade's own proof threshold is kept under. */
    public static String gradeProofThresholdKey(String grade) {
        return PROOF_THRESHOLD + "-" + grade;
    }

    /** The key a grade's grace days are kept under. */
    public static String gradeGraceKey(String grade) {
        return GRACE + "-" + grade;
    }

    /** Every value recorded for the key, oldest from-date first. */
    @Transactional(readOnly = true)
    public List<SheetSetting> history(String sheetId, String key) {
        return settings.findBySheetIdAndKeyOrderByFromAsc(sheetId, key);
    }

    @Transactional(readOnly = true)
    public BigDecimal floorOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, FLOOR, date).map(BigDecimal::new).orElse(FLOOR_START);
    }

    @Transactional(readOnly = true)
    public BigDecimal latePctOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, LATE_PCT, date).map(BigDecimal::new).orElse(LATE_PCT_START);
    }

    /** The sheet's own terms in force on the date, in days. */
    @Transactional(readOnly = true)
    public int termsOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, TERMS, date).map(Integer::valueOf).orElse(TERMS_START);
    }

    /** The grade's own terms in force on the date, in days; null when it uses the sheet's terms then. */
    @Transactional(readOnly = true)
    public Integer gradeTermsOn(String sheetId, String grade, LocalDate date) {
        return valueOn(sheetId, gradeTermsKey(grade), date).map(Integer::valueOf).orElse(null);
    }

    /** The terms a claim dated {@code date} of a person of {@code grade} is due by: the grade's own in
     * force then, or else the sheet's in force then. */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(sheetId, grade, date);
        return own != null ? own : termsOn(sheetId, date);
    }

    /** The grade's grace days in force on the date: a claim of a person of the grade then, dated then, is
     * overdue only once its due-by plus them is past; null when the grade has none then. */
    @Transactional(readOnly = true)
    public Integer gradeGraceOn(String sheetId, String grade, LocalDate date) {
        return grade == null ? null : valueOn(sheetId, gradeGraceKey(grade), date).map(Integer::valueOf).orElse(null);
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return valueOn(sheetId, CLERK_LIMIT, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The cap in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String sheetId) {
        return valueOn(sheetId, CAP, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The proof threshold in force on the date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, PROOF_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }

    /** The grade's own proof threshold in force on the date; null when it has none then. */
    @Transactional(readOnly = true)
    public BigDecimal gradeProofThresholdOn(String sheetId, String grade, LocalDate date) {
        return grade == null ? null : valueOn(sheetId, gradeProofThresholdKey(grade), date).map(BigDecimal::new).orElse(null);
    }

    /** The proof threshold of a claim dated {@code date} of a person of {@code grade}: the grade's own in
     * force then, or else the sheet's in force then; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdFor(String sheetId, String grade, LocalDate date) {
        BigDecimal own = gradeProofThresholdOn(sheetId, grade, date);
        return own != null ? own : proofThresholdOn(sheetId, date);
    }

    /** The note threshold in force on the date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal noteThresholdOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, NOTE_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }
        Set<Role> roles = EnumSet.noneOf(Role.class);
        for (String role : listed.split(",")) {
            if (!role.isBlank()) roles.add(Role.valueOf(role.trim().toUpperCase(Locale.ROOT)));
        }
        return roles;
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return dated.clerkLimit(sheetId);
    }

    /** Record the sheet's clerk limit from {@code from} (the sheet's today when null); null records no limit. */
    @Transactional
    public void setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
        record(sheetId, by, DatedSettings.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /** The floor in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdOn(String sheetId, LocalDate date) {
        return dated.proofThresholdOn(sheetId, date);
    }

    /** Record the sheet's proof threshold from {@code from} (the sheet's today when null); null records
     * no threshold. */
    @Transactional
    public void setProofThreshold(String sheetId, String by, BigDecimal threshold, LocalDate from) {
        record(sheetId, by, DatedSettings.PROOF_THRESHOLD, threshold == null ? null : threshold.toPlainString(), from, false);
    }

    /** The grades with their own proof threshold in force on the sheet's today, by grade. */
    @Transactional(readOnly = true)
    public Map<String, BigDecimal> gradeProofThresholds(String sheetId) {
        LocalDate today = today(sheetId);
        Map<String, BigDecimal> thresholds = new LinkedHashMap<>();
        for (String grade : GRADES) {
            BigDecimal own = dated.gradeProofThresholdOn(sheetId, grade, today);
            if (own != null) thresholds.put(grade, own);
        }
        return thresholds;
    }

    /** The proof threshold of a claim dated {@code date} of a person of {@code grade} (see
     * {@link DatedSettings#proofThresholdFor}). */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdFor(String sheetId, String grade, LocalDate date) {
        return dated.proofThresholdFor(sheetId, grade, date);
    }

    /** Record the grade's own proof threshold from {@code from} (the sheet's today when null); null
     * records that the grade uses the sheet's proof threshold from then. */
    @Transactional
    public void setGradeProofThreshold(String sheetId, String by, String grade, BigDecimal threshold, LocalDate from) {
        record(sheetId, by, DatedSettings.gradeProofThresholdKey(grade), threshold == null ? null : threshold.toPlainString(),
                from, false);
    }

    /** The note threshold in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal noteThreshold(String sheetId) {
    }

    /** The number a claim due by {@code date} is given when opened now: within the period containing
     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
     * period, otherwise the next sheet-wide number in the fiscal year of that date ({@code FY<yyyy>-<n>}). */
    public String nextNumber(String sheetId, LocalDate date) {
        if (!sheets.numbersByPeriod(sheetId)) return sheets.nextClaimNumber(sheetId, date);
        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
                .findFirst()
                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
    }

    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
     * the user is a clerk and the due is above the sheet's clerk limit. */
    private boolean overLimit(String sheetId, String user, BigDecimal due) {
        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
        BigDecimal limit = settings.clerkLimit(sheetId);
        return limit != null && due.compareTo(limit) > 0;
    }

    /** Refuse a settle or approval of the claim, whose due is {@code due}, when that due is above the proof
     * threshold in force on its date (its person's grade's own then, else the sheet's; a due that is n/a is
     * within any threshold) while it has no proofs, or, while the sheet lists proof kinds, no proof of one
     * of them. */
    private void refuseUnproved(Claim claim, Person person, BigDecimal due) {
        if (due == null) return;
        String kinds = settings.proofKinds(claim.getSheetId());
        boolean proved = claim.getProofs() > 0 && (kinds == null
                || Arrays.stream(kinds.split(",")).allMatch(kind -> claim.getProofsOf(kind) > 0));
        if (proved) return;
        BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
    }

    /** Whether an open of the claim goes to REVIEW: its due as it shows now is above the review threshold
     * in force on its date (a due that is n/a is within any threshold). */
    private boolean overReview(Claim claim, Person person) {
        BigDecimal due = rollup.shownOf(claim, person);
        if (due == null) return false;
        BigDecimal threshold = settings.reviewThresholdOn(claim.getSheetId(), claim.getDate());
        return threshold != null && due.compareTo(threshold) > 0;
    }

    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
    private void refuseNoteless(Claim claim, BigDecimal due) {
        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();

